// server/models/Document.js
const mongoose = require('mongoose');

const documentSchema = new mongoose.Schema(
  {
    visit: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Visit',
      required: true,
    },
    patient: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Patient',
      required: true,
    },
    // Doctor who handled the clinical records (null for auto-generated invoice)
    doctor: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
    },
    docType: {
      type: String,
      enum: [
        'INVOICE',                  // Automatically generated by system workflow
        'SICK_LEAVE',               // Generated by doctor
        'FULL_REFERRAL',            // Generated by doctor
        'OUTSOURCED_TEST',          // Generated by doctor (e.g., ultrasound)
        'OUTSOURCED_PRESCRIPTION'   // Generated by doctor
      ],
      required: true,
    },
    organizationName: {
      type: String,
      trim: true, // Used for Sick Leave (employer) or Referral/Outsourced facility
    },

    // 1. Sick Leave Details (First Check-in Date populated automatically by system)
    sickLeaveDetails: {
      firstCheckInDate: {
    type: Date,
    required: function() {
      return this.docType === 'SICK_LEAVE';
    }
  }, 
      reasonForExamination: String,
      startDate: Date,
      endDate: Date,
      numberOfDays: Number,
      remarks: String,
    },

    // 2. Full Hospital Referral Details
    fullReferralDetails: {
      clinicalFindings: String,
      labResultsSummary: String,
      currentCondition: String,
      reasonForReferral: String,
    },

    // 3. Outsourced Test Details (e.g., Ultrasound)
    outsourcedTestDetails: {
      requiredTests: [String], 
      clinicalIndication: String,
    },

    // 4. Outsourced Prescription Details
    outsourcedPrescriptionDetails: {
      medications: [
        {
          drugName: String,
          dosage: String,
          frequency: String,
          duration: String,
          instructions: String,
        }
      ],
    },

    // 5. Automatic Invoice & Payment Details
    invoiceDetails: {
      items: [
        {
          serviceName: String, // e.g., "Consultation", "Lab Test", "Procedure"
          amount: Number,
        }
      ],
      totalAmount: Number,
      paymentStatus: {
        type: String,
        enum: ['PENDING', 'PAID'],
        default: 'PENDING',
      },
      paidAt: Date,
    },

    // Reception Printing Audit Trail (Unlocked only when Invoice is PAID)
    isPrinted: {
      type: Boolean,
      default: false,
    },
    printedAt: Date,
    printedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User', // Receptionist user ID
    },
  },
  { timestamps: true }
);

module.exports = mongoose.model('Document', documentSchema);